window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.until = async (fn, ms = 15000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (await fn()) return true; await sleep(150) } return false };
window.check = (label, ok, got) => (ok ? 'OK ' : 'MISMATCH ') + label + ' got ' + JSON.stringify(got);
window.trigger = () => document.querySelector('button[aria-label^="League: "]');
window.league = () => trigger()?.getAttribute('aria-label')?.replace('League: ', '') ?? null;
window.statusLine = () => document.querySelector('[title="See what is loaded"]')?.textContent.trim() ?? null;
window.selected = (title) => [...document.querySelectorAll('select')].find((x) => x.title === title)?.selectedOptions[0]?.textContent ?? null;
window.switchTo = async (name) => { const t = trigger(); t.focus(); t.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await until(() => document.querySelectorAll('[role=menuitemradio]').length > 0, 3000); [...document.querySelectorAll('[role=menuitemradio]')].find((x) => x.textContent.startsWith(name)).click(); await until(() => league() === name, 5000); await sleep(3500); return league() };
